import { sheetProject } from '../../vite.config.ts'
import { playwright } from '@vitest/browser-playwright'
import { resolveBrowser, resolvePinnedBrowser } from '../../configs/browsers.js'

export default sheetProject('browser-design-analyst', {
	optimizeDeps: { include: ['bootstrap/js/src/modal.js', 'bootstrap/js/src/dropdown.js', 'bootstrap/js/src/tooltip.js', 'bootstrap/js/src/util/focustrap.js', 'bootstrap/js/src/util/scrollbar.js', 'bootstrap/js/src/dom/event-handler.js'] },
	test: { include: ['tmp/probes/browser-design.test.ts'], browser: {
		provider: playwright({ ...resolveBrowser(resolvePinnedBrowser(), process.platform, process.env), launchOptions: { ...resolveBrowser(resolvePinnedBrowser(), process.platform, process.env).launchOptions, ignoreDefaultArgs: ['--hide-scrollbars'] } }),
	} },
})

