import { server } from 'vitest/browser'

export function buildFixture(markup: string): HTMLDivElement {
	const root = document.createElement('div')
	root.innerHTML = markup
	document.body.append(root)
	return root
}

export function readBox(element: Element) {
	const rect = element.getBoundingClientRect()
	return { x: rect.x, y: rect.y, width: rect.width, height: rect.height, right: rect.right, bottom: rect.bottom }
}

export async function writeReading(name: string, inputs: unknown, readings: unknown, control: unknown): Promise<void> {
	await server.commands.writeFile(`tmp/probes/${name}.json`, JSON.stringify({ name, inputs, readings, control }, null, 2))
}

