import { afterAll, expect, it } from 'vitest'
import { server, userEvent } from 'vitest/browser'
import { captureError, requireValue } from '@orkestrel/test'
import { waitForFrame } from '@orkestrel/test/browser'
import EventHandler from 'bootstrap/js/src/dom/event-handler.js'
import 'bootstrap/dist/css/bootstrap.css'
import { buildFixture, readBox, writeReading } from './helpers.js'

it('measures event-name delivery and cancellation costs', async () => {
	const root = buildFixture('<button>Toggle</button>')
	const button = requireValue(root.querySelector('button'))
	const records: unknown[] = []
	const control = new AbortController()
	try {
		root.addEventListener('show.bs.dropdown', event => {
			records.push({ name: event.type, custom: event instanceof CustomEvent, bubbles: event.bubbles, cancelable: event.cancelable, related: Reflect.get(event, 'relatedTarget') === button, detail: event instanceof CustomEvent && event.detail.related === button })
			event.preventDefault()
		}, { signal: control.signal })
		root.addEventListener('show.vn.dropdown', event => records.push({ name: event.type }), { signal: control.signal })
		const oracle = EventHandler.trigger(button, 'show.bs.dropdown', { relatedTarget: button })
		const original = new CustomEvent('show.bs.dropdown', { bubbles: true, cancelable: true, detail: { related: button } })
		Object.defineProperty(original, 'relatedTarget', { value: button })
		const accepted = button.dispatchEvent(original)
		const afterSingle = records.length
		button.dispatchEvent(new CustomEvent('show.vn.dropdown', { bubbles: true, cancelable: true }))
		const afterDual = records.length
		const wrong = button.dispatchEvent(new CustomEvent('opened.bs.dropdown', { bubbles: true, cancelable: true }))
		const afterWrong = records.length
		const negative = captureError(() => expect(afterWrong).toBe(afterDual + 1))
		expect(negative).toBeDefined()
		expect(oracle.defaultPrevented).toBe(true)
		expect(accepted).toBe(false)
		expect(afterSingle).toBe(2)
		expect(afterDual).toBe(3)
		expect(wrong).toBe(true)
		await writeReading('event-contract', { oracle: 'EventHandler.trigger', candidate: 'CustomEvent with Bootstrap name, detail, relatedTarget', alternatives: ['Bootstrap only', 'Veneer only', 'both'] }, { records, oraclePrevented: oracle.defaultPrevented, candidatePrevented: !accepted, dispatchesPerTransition: { bootstrap: 1, veneer: 1, dual: 2 }, legacyDeliveries: { bootstrap: 1, veneer: 0, dual: 1 } }, { wrongName: 'opened.bs.dropdown', accepted: wrong, addedDeliveries: afterWrong - afterDual, deliberatelyWrongDeliveryAssertionFailed: negative !== undefined })
	} finally { control.abort(); root.remove() }
})

it('measures native close veto against manual ownership', async () => {
	const root = buildFixture('<button id="outside" style="position:fixed;left:10px;top:10px">Outside</button><div id="auto" popover="auto" class="dropdown-menu show" style="inset:100px auto auto 100px;margin:0">Auto</div><div id="manual" popover="manual" class="dropdown-menu show" style="inset:200px auto auto 100px;margin:0">Manual</div>')
	const auto = requireValue(root.querySelector<HTMLElement>('#auto'))
	const manual = requireValue(root.querySelector<HTMLElement>('#manual'))
	const events: unknown[] = []
	try {
		auto.addEventListener('beforetoggle', event => {
			if (!(event instanceof ToggleEvent)) return
			if (event.newState === 'closed') event.preventDefault()
			events.push({ state: event.newState, cancelable: event.cancelable, prevented: event.defaultPrevented })
		})
		auto.showPopover()
		await userEvent.click(requireValue(root.querySelector<HTMLButtonElement>('#outside')))
		await waitForFrame()
		await waitForFrame()
		const automatic = { open: auto.matches(':popover-open'), display: getComputedStyle(auto).display, box: readBox(auto), events }
		manual.showPopover()
		manual.addEventListener('hide.bs.dropdown', event => event.preventDefault())
		const accepted = manual.dispatchEvent(new CustomEvent('hide.bs.dropdown', { bubbles: true, cancelable: true }))
		if (accepted) manual.hidePopover()
		const controlled = { accepted, open: manual.matches(':popover-open') }
		const negative = captureError(() => expect(automatic.open).toBe(true))
		expect(negative).toBeDefined()
		expect(controlled.open).toBe(true)
		expect(automatic.display).toBe('block')
		await writeReading('close-veto', { markup: root.innerHTML, action: 'outside click, preventDefault on closing beforetoggle; gated manual hide' }, { automatic, controlled }, { assertion: 'automatic popover remains open after veto', failed: negative !== undefined })
	} finally { if (auto.matches(':popover-open')) auto.hidePopover(); if (manual.matches(':popover-open')) manual.hidePopover(); root.remove() }
})

it('measures ordinary-layer anchor fallback and anchored queries', async () => {
	const root = buildFixture('<button id="anchor" style="position:fixed;left:100px;top:120px;width:70px;height:30px;anchor-name:--design-anchor">Anchor</button><div id="panel" class="dropdown-menu show" style="position:fixed;position-anchor:--design-anchor;position-area:bottom;position-try-fallbacks:flip-block;inset:auto;margin:0;width:160px;height:80px;container-type:anchored"><span id="marker">Menu</span></div>')
	const anchor = requireValue(root.querySelector<HTMLElement>('#anchor'))
	const panel = requireValue(root.querySelector<HTMLElement>('#panel'))
	const marker = requireValue(root.querySelector<HTMLElement>('#marker'))
	const sheet = new CSSStyleSheet()
	sheet.replaceSync('#marker { --resolved: bottom; } @container anchored(fallback: flip-block) { #marker { --resolved: top; } }')
	document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet]
	try {
		await waitForFrame()
		await waitForFrame()
		const before = { anchor: readBox(anchor), panel: readBox(panel), area: getComputedStyle(panel).positionArea, marker: getComputedStyle(marker).getPropertyValue('--resolved') }
		anchor.style.top = `${innerHeight - 40}px`
		await waitForFrame()
		await waitForFrame()
		const edge = { anchor: readBox(anchor), panel: readBox(panel), area: getComputedStyle(panel).positionArea, marker: getComputedStyle(marker).getPropertyValue('--resolved') }
		panel.style.positionTryFallbacks = 'none'
		await waitForFrame()
		await waitForFrame()
		const without = { anchor: readBox(anchor), panel: readBox(panel), marker: getComputedStyle(marker).getPropertyValue('--resolved') }
		const negative = captureError(() => expect(without.panel.bottom).toBeLessThanOrEqual(without.anchor.y))
		expect(negative).toBeDefined()
		expect(before.panel.y).toBeCloseTo(before.anchor.bottom, 0)
		expect(edge.panel.bottom).toBeLessThanOrEqual(edge.anchor.y)
		await writeReading('anchor-resolution', { viewport: { width: innerWidth, height: innerHeight }, sheet: [...sheet.cssRules].map(rule => rule.cssText), css: 'ordinary fixed box, bottom, flip-block, container-type:anchored' }, { supported: CSS.supports('container-type', 'anchored'), before, edge }, { without, deliberatelyWrongAboveAssertionFailed: negative !== undefined })
	} finally { document.adoptedStyleSheets = document.adoptedStyleSheets.filter(value => value !== sheet); root.remove() }
})

it('measures intrinsic horizontal width against Bootstrap scrollWidth', async () => {
	const root = buildFixture('<div style="width:300px"><div class="collapsing collapse-horizontal" id="panel" style="width:0;interpolate-size:allow-keywords"><div style="width:120px;height:40px">Content</div></div></div>')
	const panel = requireValue(root.querySelector<HTMLElement>('#panel'))
	try {
		void panel.offsetWidth
		const scroll = panel.scrollWidth
		const transition = getComputedStyle(panel).transition
		panel.style.width = 'auto'
		const animations = panel.getAnimations().map(animation => ({ keyframes: animation.effect instanceof KeyframeEffect ? animation.effect.getKeyframes() : [] }))
		await Promise.allSettled(panel.getAnimations().map(animation => animation.finished))
		const automatic = readBox(panel)
		panel.style.transition = 'none'
		panel.style.width = `${scroll}px`
		const numeric = readBox(panel)
		const negative = captureError(() => expect(automatic.width).toBe(numeric.width))
		expect(negative).toBeDefined()
		expect(scroll).toBe(120)
		await writeReading('horizontal-intrinsic', { parent: 300, child: 120, transition, interpolated: '0 to auto' }, { scroll, automatic, numeric, animations }, { assertion: 'auto target equals Bootstrap scrollWidth target', failed: negative !== undefined })
	} finally { root.remove() }
})

it('measures dialog receiver constraints and focus false mismatch', async () => {
	const root = buildFixture('<button id="opener">Opener</button><div class="modal" id="div"></div><dialog class="modal" id="dialog" style="display:block"><button id="inner">Inside</button></dialog>')
	const div = requireValue(root.querySelector<HTMLElement>('#div'))
	const dialog = requireValue(root.querySelector<HTMLDialogElement>('#dialog'))
	const opener = requireValue(root.querySelector<HTMLButtonElement>('#opener'))
	try {
		const refused = captureError(() => Reflect.apply(HTMLDialogElement.prototype.showModal, div, []))
		opener.focus()
		dialog.showModal()
		opener.focus()
		const native = { modal: dialog.matches(':modal'), focused: document.activeElement?.id, ordinaryHasMethod: 'showModal' in div, refusal: String(refused) }
		dialog.close()
		opener.focus()
		const control = { focused: document.activeElement?.id }
		const negative = captureError(() => expect(native.focused).toBe('opener'))
		expect(negative).toBeDefined()
		expect(refused).toBeDefined()
		expect(control.focused).toBe('opener')
		await writeReading('dialog-contract', { tags: ['div.modal', 'dialog.modal'], action: 'borrow showModal, then native showModal and attempt outside focus' }, native, { ordinary: control, focusFalseAssertionFailed: negative !== undefined })
	} finally { if (dialog.open) dialog.close(); root.remove() }
})

afterAll(async () => {
	const names = ['event-contract', 'close-veto', 'anchor-resolution', 'horizontal-intrinsic', 'dialog-contract']
	const readings: unknown[] = []
	for (const name of names) readings.push(JSON.parse(await server.commands.readFile(`tmp/probes/${name}.json`)))
	const sources: Record<string, string> = {}
	for (const name of ['vite.chromium.config.ts', 'helpers.ts', 'browser-design.test.ts']) sources[name] = await server.commands.readFile(`tmp/probes/${name}`)
	await server.commands.writeFile('tmp/units/browser-design-analyst-measurements.json', JSON.stringify({ date: new Date().toISOString(), browser: navigator.userAgent, recipe: 'npx vitest run --config tmp/probes/vite.chromium.config.ts tmp/probes/browser-design.test.ts', baseline: 'tmp/units/browser-feasibility-measurements.json', sources, probes: readings }, null, 2))
})
